# Initialize the phonebook as an empty dictionary
phonebook = {}

def add_contact():
    """Add a new contact to the phonebook."""
    name = input("Enter the name of the contact: ").strip()
    number = input("Enter the phone number: ").strip()

    # Check if the name already exists in the phonebook
    if name in phonebook:
        print(f"Contact {name} already exists. Would you like to update the number? (yes/no)")
        update = input().lower()
        if update == "yes":
            phonebook[name] = number
        else:
            print(f"Contact {name} was not updated.")
    else:
        phonebook[name] = number

    print(f"Phonebook:")
    print_contacts()

def remove_contact():
    """Remove a contact from the phonebook."""
    name = input("Enter the name of the contact to remove: ").strip()

    if name in phonebook:
        del phonebook[name]
        print(f"Contact {name} was removed from the phonebook.")
    else:
        print(f"Contact {name} was not found in the phonebook.")

    print(f"Phonebook:")
    print_contacts()

def print_contacts():
    """Print all contacts in the phonebook."""
    for name, number in phonebook.items():
        print(f"{name}: {number}")

def main():
    print("Welcome to the Phonebook!")
    while True:
        print("\nEnter 'add' to add a contact, 'remove' to remove a contact, or 'view' to view all contacts.")
        command = input().lower()

        if command == "add":
            add_contact()
        elif command == "remove":
            remove_contact()
        elif command == "view":
            print_contacts()
        else:
            print("Invalid command. Please try again.")
        break

if __name__ == "__main__":
    main()
```

This program allows the user to add, remove, and view contacts in a phonebook. You can customize it further by adding more options or error handling.
